'use client'

import { usePathname } from 'next/navigation'
import { toggleNotifications } from '@/app/actions/notifications'

type Props = { enabled: boolean }

export function NotificationToggle({ enabled }: Props) {
  const pathname = usePathname()
  const action = toggleNotifications.bind(null, pathname)

  return (
    <form action={action}>
      <button type="submit">{enabled ? 'Turn off' : 'Turn on'}</button>
    </form>
  )
}

