import { cookies } from 'next/headers'
import { NotificationToggle } from '@/app/components/notification-toggle'
import { NOTIFICATIONS_COOKIE, notificationsEnabledFromCookie } from '@/lib/notifications-preference'

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = notificationsEnabledFromCookie(cookieStore.get(NOTIFICATIONS_COOKIE)?.value)

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{enabled ? 'on' : 'off'}</strong>.
      </p>
      <NotificationToggle enabled={enabled} />
    </main>
  )
}

